/** Bundled example sources and renders (generated by scripts/examples.ts into public/examples). */
export const SAMPLE_SOURCES = ['jellyfish', 'planet', 'clouds', 'orbs'] as const;
export type SampleSource = (typeof SAMPLE_SOURCES)[number];

export const EXAMPLES: { source: SampleSource; preset: string }[] = [
  { source: 'jellyfish', preset: 'soft-ascii' },
  { source: 'jellyfish', preset: 'cross' },
  { source: 'planet', preset: 'cross' },
  { source: 'jellyfish', preset: 'dither-scanline' },
  { source: 'clouds', preset: 'dots' },
  { source: 'orbs', preset: 'gameboy-dither' },
];

export const exampleUrl = (file: string) => new URL(`examples/${file}`, document.baseURI).href;

export async function loadSample(name: SampleSource): Promise<ImageBitmap> {
  const res = await fetch(exampleUrl(`${name}.jpg`));
  if (!res.ok) throw new Error(`sample ${name}: ${res.status}`);
  return createImageBitmap(await res.blob());
}
